"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "motion/react";
import { Play, RotateCcw } from "lucide-react";
import { cn } from "@/lib/utils";

export interface LoadingLineRevealProps
  extends React.HTMLAttributes<HTMLDivElement> {
  galleryImages?: string[];
}

const DEFAULT_GALLERY = [
  "https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=600&q=80",
  "https://images.unsplash.com/photo-1511497584788-87676104235f?auto=format&fit=crop&w=600&q=80",
  "https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=600&q=80",
  "https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=600&q=80",
];

export function LoadingLineReveal({
  galleryImages = DEFAULT_GALLERY,
  className,
  ...props
}: LoadingLineRevealProps) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [isRevealed, setIsRevealed] = useState(false);

  const startReveal = () => {
    setIsPlaying(true);
    setIsRevealed(false);
  };

  const handleReset = () => {
    setIsPlaying(false);
    setIsRevealed(false);
  };

  return (
    <div
      data-slot="loading-line-reveal"
      className={cn(
        "relative flex flex-col items-center justify-center select-none w-full max-w-xl mx-auto gap-4",
        className
      )}
      {...props}
    >
      <div className="relative w-full aspect-video overflow-hidden rounded-3xl border border-neutral-200 dark:border-neutral-800 bg-neutral-950 shadow-2xl">
        {/* Underlying Gallery Grid */}
        <div className="grid h-full w-full grid-cols-2 grid-rows-2 gap-2 p-2 bg-neutral-900">
          {galleryImages.map((src, i) => (
            <div key={src + i} className="overflow-hidden rounded-xl">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={src}
                alt="Gallery item"
                className="h-full w-full object-cover"
              />
            </div>
          ))}
        </div>

        {/* Black Curtain Overlay with Center Line Expansion */}
        <AnimatePresence>
          {!isRevealed ? (
            <motion.div
              initial={{ clipPath: "polygon(0 0, 100% 0, 100% 100%, 0 100%)" }}
              animate={
                isPlaying
                  ? {
                      clipPath: [
                        "polygon(0 0, 100% 0, 100% 100%, 0 100%)",
                        "polygon(49.8% 0, 50.2% 0, 50.2% 100%, 49.8% 100%)",
                        "polygon(50% 50%, 50% 50%, 50% 50%, 50% 50%)",
                      ],
                    }
                  : { clipPath: "polygon(0 0, 100% 0, 100% 100%, 0 100%)" }
              }
              transition={{
                duration: 1.2,
                times: [0, 0.45, 1],
                ease: [0.76, 0, 0.24, 1],
              }}
              onAnimationComplete={() => {
                if (isPlaying) setIsRevealed(true);
              }}
              className="absolute inset-0 z-10 bg-neutral-950 flex items-center justify-center"
            >
              {/* Pink Vertical Laser / Beam Line */}
              <motion.div
                animate={
                  isPlaying
                    ? {
                        height: ["0%", "100%", "100%"],
                        opacity: [0, 1, 0],
                        scaleX: [1, 2, 400],
                      }
                    : { height: "0%", opacity: 0 }
                }
                transition={{
                  duration: 1.2,
                  times: [0, 0.45, 1],
                  ease: "easeInOut",
                }}
                className="w-1 bg-pink-500 shadow-[0_0_15px_#ec4899] rounded-full"
              />
            </motion.div>
          ) : null}
        </AnimatePresence>
      </div>

      {/* Control Buttons */}
      <div className="flex items-center gap-3">
        <button
          type="button"
          onClick={startReveal}
          disabled={isPlaying && !isRevealed}
          className="flex items-center gap-2 rounded-full bg-pink-500 px-5 py-2.5 text-xs font-bold text-white shadow-lg transition-transform hover:bg-pink-600 active:scale-95 disabled:opacity-50 cursor-pointer"
        >
          <Play className="h-3.5 w-3.5 fill-current" />
          <span>Trigger Line Reveal</span>
        </button>

        {isRevealed ? (
          <button
            type="button"
            onClick={handleReset}
            className="flex items-center gap-1.5 rounded-full border border-neutral-200 bg-neutral-100 px-4 py-2.5 text-xs font-semibold text-neutral-800 transition-colors hover:bg-neutral-200 dark:border-neutral-800 dark:bg-neutral-800 dark:text-neutral-200 dark:hover:bg-neutral-700 cursor-pointer"
          >
            <RotateCcw className="h-3.5 w-3.5" />
            <span>Reset Overlay</span>
          </button>
        ) : null}
      </div>
    </div>
  );
}
